-- O cadastro do Painel de Bordo (17/10/2026): a tabela dos itens, já com os itens das abas Resultados e Performance de
-- antes (na mesma ordem, cada um com o modelo de apuração dele), e a assinatura do cadastro na apuração da competência.
ALTER TABLE "competencias" ADD COLUMN "painel_assinatura" TEXT;

CREATE TABLE "painel_itens" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "grupo" TEXT NOT NULL,
    "quadro" TEXT NOT NULL,
    "nome" TEXT NOT NULL,
    "sigla" TEXT NOT NULL,
    "sentido" TEXT NOT NULL,
    "modelo" TEXT NOT NULL,
    "ordem" INTEGER NOT NULL DEFAULT 0,
    "ativo" BOOLEAN NOT NULL DEFAULT true,
    "criado_em" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "atualizado_em" DATETIME NOT NULL
);


-- A aba Painel de Bordo da tela Analítico: quem tinha a Estrutura dos Indicadores ganha a mesma permissão nela.
INSERT OR IGNORE INTO "perfil_permissoes_telas" ("perfil_id", "chave", "acao") SELECT "perfil_id", 'cadastro_analitico.painel_bordo', "acao" FROM "perfil_permissoes_telas" WHERE "chave" = 'cadastro_analitico.estrutura_indicadores';
